213: Let $\Lambda=\Lambda(x_1,x_2,\ldots)$ be the ring of symmetric functions with integral coefficients. This space has a ${\mathbb Z}$-linear basis consisting of \emph{Schur functions} $s_{\lambda}$,
214: where $\lambda$ is an integer partition. Consider the ideal
215: \[I_{r,n-r} = \mathrm{Span}_\mathbb{Z}\left\{s_\lambda\mid \lambda\nsubseteq (n-r)^r \right\} \]
216: of $\Lambda$. Then one has the following standard presentation of the cohomology of Grassmannians:
217: \[H^*(\mathrm{Gr}_{r,n})\cong \Lambda/I_{r,n-r}. \]
218: We will use an overline to denote the projection $\Lambda\to\Lambda/I_{r,n-r}$. Specifically, we will write $\overline{\Lambda}$ as a shorthand for $\Lambda/I_{r,n-r}$. We will also distinguish between $s_{\lambda}\in \Lambda$, the usual Schur function, and $\overline{s}_{\lambda}$ for its image in $\overline{\Lambda}$.
219: We resolve the minimality conjecture \cite[Conjecture~4.10]{RWY} about the basic ideals $J_v$:
220: \begin{theorem}\label{thm:main}
221: Given a bigrassmannian permutation $v=v_{r,s,t,n}\in S_n$ let
222: \begin{align*}
223: i&\coloneqq s-t+1,\\
224: j&\coloneqq r-t+1,\\
225: a&\coloneqq \min(n-r-i,r-j),\\
226: b&\coloneqq \min(i,j).
227: \end{align*}
228: Then the basic ideal $J_v$, thought of as an ideal of $H^*(\mathrm{Gr}_{r,n})\cong \Lambda/I_{r,n-r}$, is minimally generated by
229: \begin{equation}
230: \label{eqn:minimallist}
231: \{\overline{s}_{\mu} \mid i^j\subseteq \mu \subseteq (i^j,b^a)\}.
232: \end{equation}
233: \end{theorem}
234: That (\ref{eqn:minimallist}) generates $J_v$ is \cite[Theorem 4.8]{RWY}. The conjectural part, which we prove,
235: is the minimality claim, that is, no generator can be removed without changing the ideal.

790: \begin{theorem}
791: \label{thm:inconsistent}
792: For any valid $\varphi=(n,r,i,j,a,b,N)$, the equations
793: \begin{equation}
794: \label{eqn:all-equations}
795: \left\{ \linear_{\varphi}(\nu) = d_{\nu}\mid \nu\in \decomp_{\varphi} \right\}
796: \end{equation}
797: are inconsistent whenever $d_{\nu}=0$ for all wide $\nu$, and $d_{\rho}\neq 0$ for some tall $\rho$.
798: \end{theorem}
799: \begin{proof}
800: Suppose first that
801: \[N\leq \min(j,n-r-i).\] By Lemma \ref{lem:tall-dependent-on-wide}, we have $\linear_{\varphi}(\rho) \in W$.
802: The restriction $d_\nu=0$ when $\nu$ is wide would then force $d_{\rho}=0$, contradicting the hypothesis. Thus the equations (\ref{eqn:all-equations}) are inconsistent.
803: Now suppose that
804: \[N>\min(j,n-r-i).\]
805: Choose $q$ so that $N\leq \min(2^qj,4^qn-2^qr-i)$. Let
806: \[\widehat{\varphi} = (\widehat{n},\widehat{r},i,\widehat{j},a,b,N),\quad \mbox{where} \quad \widehat{n}=4^qn,\quad \widehat{r}=2^qr,\quad\mbox{and}\quad \widehat{j}=2^qj.\]
807: For each $\nu\in \decomp_{\varphi}$, let $\widehat{\nu}\in\decomp_{\widehat{\varphi}}$ be the partition with $\widehat{\nu}_B=\nu_B$ and $\widehat{\nu}_R=\nu_R$. For $\tau\in\decomp_{\widehat{\varphi}}$, define
808: \[e_{\tau} = \begin{cases}
809: d_\nu &\mbox{ if } \tau=\widehat{\nu} \mbox{ for some } \nu\in\decomp_{\varphi},\\
810: 0 &\mbox{ otherwise.}
811: \end{cases} \]
812: By the previous argument, the equations
813: \begin{equation}
814: \label{eqn:bigger_m}
815: \left\{ \linear_{\widehat{\varphi}}(\tau) = e_{\tau}\mid \tau\in \decomp_{\widehat{\varphi}} \right\}
816: \end{equation}
817: are inconsistent. By Lemma \ref{lem:restricting-equations}, the equations (\ref{eqn:all-equations}) can be obtained by setting certain variables to zero in (\ref{eqn:bigger_m}). Setting variables to zero in an inconsistent linear system produces the same.
818: \end{proof}
819: \begin{theorem}
820: For any valid $\varphi=(n,r,i,j,a,b,N)$, there is no syzygy of the form
821: \[\sum_{\substack{\lambda\subseteq b^a\\|\lambda|=N}}\overline{s}_{(i^j,\lambda)}f_{\lambda}=\sum_{\substack{\lambda\subseteq b^a\\|\lambda|<N }}f_{\lambda}\overline{s}_{(i^j,\lambda)}\]
822: with the left-hand side nonzero.
823: \end{theorem}
824: \begin{proof}
825: By Lemma \ref{lem:implication-of-syzygy}, the existence of such a syzygy would contradict Theorem \ref{thm:inconsistent}.
826: \end{proof}
827: \begin{corollary}
828: \label{cor:no-syzygy}
829: For any bigrassmannian $v=v_{r,s,t,n}\in S_n$ and $i,j,a,b$ as in Theorem \ref{thm:main}, the generating set
830: \[\{\overline{s}_{\mu} \mid i^j\subseteq \mu \subseteq (i^j,b^a)\}\]
831: of $J_v$ in $\overline{\Lambda}$ is minimal.

777: \begin{lemma}
778: \label{lem:restricting-equations}
779: Suppose $\varphi=(n,r,i,j,a,b,N)$ be valid. Set $\widehat{\varphi}=(\widehat{n},\widehat{r},i,\widehat{j},a,b,N)$ where $\widehat{n}=4^qn$, $\widehat{r}=2^q r$, and $\widehat{j}=2^q j$ for $q\in {\mathbb N}$. Fix any $\nu\in \decomp_{\varphi}$, and let $\widehat{\nu}\in\decomp_{\widehat{\varphi}}$ be the partition with
780: \[\widehat{\nu}_B=\nu_B \quad\mbox{and}\quad \widehat{\nu}_R=\nu_R.\]
781: Then setting the variables
782: \[\{A_{\lambda,\theta} \mid \lambda\nsubseteq b^a \mbox{ or } \theta\nsubseteq (n-r-i)^j \}\]
783: to zero in $\linear_{\widehat{\varphi}}(\widehat{\nu})$ yields exactly $\linear_{\varphi}(\nu)$.
784: \end{lemma}
785: \begin{proof}
786: It suffices to note that
787: \[c_{(i^j,\lambda),\theta}^{\nu}= c_{(i^{\widehat{j}}\lambda),\theta}^{\widehat{\nu}}\]
788: by Theorem \ref{thm:pictures}, since the skew shapes $\nu/(i^j,\lambda)$ and $\widehat{\nu}/(i^{\widehat{j}}\lambda)$ are (essentially) the same.
789: \end{proof}
